(44195, 'Psalms 41:12', 'Psalms', 41, 12, 'راسره کړی دې کومک ځکه صادق یمه زه په خپل حضور کې مې ساتې ته تر ابده پورې', 'راسره کری دې کومک جکه صادق یمه زه په خپل حضور کې مې ساتې ته تر ابده پورې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_41_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44196, 'Psalms 41:13', 'Psalms', 41, 13, 'ثنا او صفت دې وي د اسراییلو څښتن خدای ته وکړئ ثنا او صفت یې د ازل نه تر ابده پورې امین! امین!', 'ثنا او صفت دې وی د اسراییلو چشتن خدای ته وکری ثنا او صفت یې د ازل نه تر ابده پورې امین! امین!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_41_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44197, 'Joshua 15:1', 'Joshua', 15, 1, 'د یهودا د قبیلې طایفو د ځمکې یوه برخه تر لاسه کړه چې په لاندې ډول تشریح کیږي. دا ځمکه د صین د دښتې جنوب یعنې د ادوم د پولې پورې رسېدله.', 'د یهودا د قبیلې طایفو د جمکې یوه برخه تر لاسه کره چې په لاندې دول تشریح کیزی. دا جمکه د صین د دشتې جنوب یعنې د ادوم د پولې پورې رسېدله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44198, 'Joshua 15:2', 'Joshua', 15, 2, 'دا جنوبي پوله د مړې بحیرې د جنوبي برخې په پای کې پیل شوې،', 'دا جنوبی پوله د مرې بحیرې د جنوبی برخې په پای کې پیل شوې،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44199, 'Joshua 15:3', 'Joshua', 15, 3, 'د عقربیم د غاښي جنوب خواته تللې، د صین تر دښتې پورې غزېدلې ده او د قادش برنیع تر جنوب پورې وه. بیا هغه د حزرون څخه تېره شوې، پورته د ادار خواته تللې او د قرقع خواته ګرځېدلې ده.', 'د عقربیم د غاشی جنوب خواته تللې، د صین تر دشتې پورې غزېدلې ده او د قادش برنیع تر جنوب پورې وه. بیا هغه د حزرون چخه تېره شوې، پورته د ادار خواته تللې او د قرقع خواته ګرجېدلې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44200, 'Joshua 15:4', 'Joshua', 15, 4, 'هغه د عصمون څخه تېره شوې او د هغه خوړ سره یوځای شوې ده چې د مصر د پولې سره ؤ او د مدیترانې په بحیره کې ختمه شوې ده. دا د ټولو اسراییلو جنوبي پوله هم وه.', 'هغه د عصمون چخه تېره شوې او د هغه خور سره یوجای شوې ده چې د مصر د پولې سره و او د مدیترانې په بحیره کې ختمه شوې ده. دا د تولو اسراییلو جنوبی پوله هم وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44201, 'Joshua 15:5', 'Joshua', 15, 5, 'د یهودا د قبیلې ختیځه پوله مړه بحیره وه. دا پوله په شمال کې تر هغه ځای پورې غزېدلې ده په کوم ځای کې چې د اردن سیند د مړې بحیرې سره یوځای کیږي', 'د یهودا د قبیلې ختیجه پوله مره بحیره وه. دا پوله په شمال کې تر هغه جای پورې غزېدلې ده په کوم جای کې چې د اردن سیند د مرې بحیرې سره یوجای کیزی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44202, 'Joshua 15:6', 'Joshua', 15, 6, 'او هغه تر بیت حجله پورې غزېدلې ده، د بیت عربه شمال خواته تللې او د هغه ځای څخه د بوهن ګټ ته راوتلې ده. (بوهن د روبین زوی ؤ.)', 'او هغه تر بیت حجله پورې غزېدلې ده، د بیت عربه شمال خواته تللې او د هغه جای چخه د بوهن ګت ته راوتلې ده. (بوهن د روبین زوی و.)', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44203, 'Joshua 15:7', 'Joshua', 15, 7, 'او دا پوله بیا د مصیبت له درې څخه پورته دبیر ته راوتلې او د شمال خواته د جلجال په لوري چې د درې په جنوب کې د ادومیم غاښي ته مخامخ ده، ګرځېدلې ده. بیا هغه د عین شمس د چینو خواته تللې او په عین روجل کې راوتلې ده.', 'او دا پوله بیا د مصیبت له درې چخه پورته دبیر ته راوتلې او د شمال خواته د جلجال په لوری چې د درې په جنوب کې د ادومیم غاشی ته مخامخ ده، ګرجېدلې ده. بیا هغه د عین شمس د چینو خواته تللې او په عین روجل کې راوتلې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44204, 'Joshua 15:8', 'Joshua', 15, 8, 'بیا دا پوله د غونډۍ جنوب خواته د هنوم د زوی د درې په لاره تېره شوې ده چېرته چې د یبوسیانو ښار یعنې اورشلیم پروت ؤ. دا پوله بیا د هغې غونډۍ سرته رسیږي چې د هنوم د درې په لوېدیځه خوا کې وه چې د رفاییم د درې شمالي برخه وه.', 'بیا دا پوله د غوندی جنوب خواته د هنوم د زوی د درې په لاره تېره شوې ده چېرته چې د یبوسیانو شار یعنې اورشلیم پروت و. دا پوله بیا د هغې غوندی سرته رسیزی چې د هنوم د درې په لوېدیجه خوا کې وه چې د رفاییم د درې شمالی برخه وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44205, 'Joshua 15:9', 'Joshua', 15, 9, 'د هغه ځای څخه دا پوله د نفتوح چینې او بیا هغو ښارګوټو ته تللې ده چې د عفرون غر ته نژدې وو. دا پوله هلته د بعله خواته ګرځېدلې ده چې اوس د قریت یعاریم په نوم یادیږي،', 'د هغه جای چخه دا پوله د نفتوح چینې او بیا هغو شارګوتو ته تللې ده چې د عفرون غر ته نژدې وو. دا پوله هلته د بعله خواته ګرجېدلې ده چې اوس د قریت یعاریم په نوم یادیزی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44206, 'Joshua 15:10', 'Joshua', 15, 10, 'چېرته چې دغه پوله د ادوم د غرنۍ سیمې په خوا کې د بعله د لوېدیځ څخه راچاپېره شوې ده. بیا هغه د یعاریم د غره شمالي خوا (کسالون) ته تللې، ښکته بیت شمس ته راوتلې او د تمنه څخه تېریږي.', 'چېرته چې دغه پوله د ادوم د غرنی سیمې په خوا کې د بعله د لوېدیج چخه راچاپېره شوې ده. بیا هغه د یعاریم د غره شمالی خوا (کسالون) ته تللې، شکته بیت شمس ته راوتلې او د تمنه چخه تېریزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44207, 'Joshua 15:11', 'Joshua', 15, 11, 'بیا دا پوله هغې غونډۍ ته وتلې ده چې د عقرون په شمال کې ده. بیا د شکرون خواته ګرځېدلې، د بعله د غره څخه تېره شوې او یبییل ته راوتلې ده. دا پوله د مدیترانې په بحیره کې ختمه شوې ده', 'بیا دا پوله هغې غوندی ته وتلې ده چې د عقرون په شمال کې ده. بیا د شکرون خواته ګرجېدلې، د بعله د غره چخه تېره شوې او یبییل ته راوتلې ده. دا پوله د مدیترانې په بحیره کې ختمه شوې ده', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44208, 'Joshua 15:12', 'Joshua', 15, 12, 'او هلته یې لوېدیځه پوله جوړه کړې ده. د یهودا خلک په دې سرحدونو کې اوسېدل.', 'او هلته یې لوېدیجه پوله جوره کرې ده. د یهودا خلک په دې سرحدونو کې اوسېدل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44209, 'Joshua 15:13', 'Joshua', 15, 13, 'څنګه چې څښتن یوشع ته حکم کړی ؤ، د یهودا د سیمې یوه برخه د یفنه زوی کالیب ته چې د یهودا د قبیلې څخه ؤ ورکړل شوه. هغه قریت اربع یعنې د حبرون ښار چې د عناق د نیکه یعنې اربع پورې یې اړه درلودله تر لاسه کړ.', 'چنګه چې چشتن یوشع ته حکم کری و، د یهودا د سیمې یوه برخه د یفنه زوی کالیب ته چې د یهودا د قبیلې چخه و ورکرل شوه. هغه قریت اربع یعنې د حبرون شار چې د عناق د نیکه یعنې اربع پورې یې اره درلودله تر لاسه کر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44210, 'Joshua 15:14', 'Joshua', 15, 14, 'کالیب د عناق اولاده یعنې د شیشای، اخیمان او تلمای طایفې د ښار څخه وشړلې.', 'کالیب د عناق اولاده یعنې د شیشای، اخیمان او تلمای طایفې د شار چخه وشرلې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44211, 'Joshua 15:15', 'Joshua', 15, 15, 'کالیب د هغه ځای څخه د دبیر په اوسېدونکو باندې د حملې دپاره لاړ. (دا ښار مخکې د قریت سفر په نوم یادېده.)', 'کالیب د هغه جای چخه د دبیر په اوسېدونکو باندې د حملې دپاره لار. (دا شار مخکې د قریت سفر په نوم یادېده.)', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44212, 'Joshua 15:16', 'Joshua', 15, 16, 'کالیب وویل: «هرچا چې قریت سفر فتح کړ، زه به خپله لور عکسه هغه ته په نکاح ورکړم.»', 'کالیب وویل: «هرچا چې قریت سفر فتح کر، زه به خپله لور عکسه هغه ته په نکاح ورکرم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44213, 'Joshua 15:17', 'Joshua', 15, 17, 'عتني ییل د کالیب د ورور قناز زوی هغه ښار ونیوه، نو کالیب خپله لور هغه ته په نکاح ورکړه.', 'عتنی ییل د کالیب د ورور قناز زوی هغه شار ونیوه، نو کالیب خپله لور هغه ته په نکاح ورکره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44214, 'Joshua 15:18', 'Joshua', 15, 18, 'د واده په ورځ عتني ییل هغه وهڅوله چې د خپل پلار څخه یو پټی وغواړي. عکسه د خپل خره څخه ښکته شوه او کالیب د هغې څخه پوښتنه وکړه: «څه غواړې؟»', 'د واده په ورج عتنی ییل هغه وهچوله چې د خپل پلار چخه یو پتی وغواری. عکسه د خپل خره چخه شکته شوه او کالیب د هغې چخه پوشتنه وکره: «چه غوارې؟»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_15_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
